\t on
\o drawing.html

WITH src AS
( SELECT   type
         , 5+ROUND((x - minx) * scale, 0) AS x
         , 5+ROUND((y - miny) * scale, 0) AS y
         , GREATEST(5, ROUND(r * scale, 0)) AS r
         , ROUND(w * scale, 0) AS w
         , ROUND(h * scale, 0) AS h
         , line_colour, line_weight, line_opacity, fill_colour, fill_opacity
         , minx, miny, maxx, maxy , scale, points
         , x AS ox, y AS oy, r AS orr, w AS ow, h AS oh
  FROM     draw AS d
  JOIN ( SELECT LEAST(MIN(x-r), MIN(x+w), MIN(x)) AS minx
              , GREATEST(MAX(x+r), MAX(x+w), MAX(x+w)) AS maxx
              , LEAST(MIN(y-r), MIN(y+h), MIN(y)) AS miny
              , GREATEST(MAX(y+r), MAX(y+h), MAX(y+h)) AS maxy
              , LEAST( (1000 / ( GREATEST(MAX(x+r), MAX(x+w), MAX(x)) - LEAST(MIN(x-r), MIN(x+w), MIN(x)) ) )
                     , (500  / ( GREATEST(MAX(y+r), MAX(y+h), MAX(y)) - LEAST(MIN(y-r), MIN(y+h), MIN(y)) ) ) ) AS scale
         FROM draw ) AS mm
  ON   ( 1 = 1 ) )
--SELECT * FROM src;
SELECT '<!DOCTYPE html><html><body><svg width="1000" height="600">'
UNION ALL
SELECT DISTINCT 'minx:'||minx||' maxx:'||maxx||' miny:'||miny||' maxy:'||maxy||' scale:'||scale
FROM src
UNION ALL
SELECT '<rect x="0" y="0" width="1000" height="500"'
     ||' style="fill:#EEEEEE;stroke-width:0" />'
UNION ALL
SELECT
  CASE WHEN type = 'circle' THEN
          '<circle cx="'||x||'" cy="'||y||'" r="'||r||'"'
       WHEN type = 'rect' THEN
          '<rect x="'||x||'" y="'||y||'" width="'||w||'" height="'||h||'"'
       WHEN type = 'line' THEN
          '<line x1="'||x||'" y1="'||y||'" x2="'||x+w||'" y2="'||y+h||'"'
       --Need to scale points in polyline... how?
       --WHEN type = 'polyline' THEN
          --'<polyline points="'||points||'"'
  END
  ||' style="fill:blue;stroke:blue;stroke-width:'
  ||CASE WHEN type IN ('line', 'polyline') THEN COALESCE(line_weight,2)
         ELSE COALESCE(line_weight,0)
    END
  ||';fill-opacity:0.1;stroke-opacity:0.9" />'
FROM
  src
UNION ALL
SELECT '</svg></body></html>'
;

\o
\t off

\! type drawing.html
